PRAGMA foreign_keys = ON;
PRAGMA journal_mode = WAL;
CREATE TABLE roles (name TEXT PRIMARY KEY);
CREATE TABLE users (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, role TEXT NOT NULL REFERENCES roles(name), area TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)));
CREATE TABLE sites (id TEXT PRIMARY KEY, name TEXT NOT NULL, area TEXT NOT NULL, feeder TEXT, capacity_kw REAL NOT NULL, has_battery INTEGER NOT NULL, source_mode TEXT NOT NULL DEFAULT 'synthetic');
CREATE TABLE inverters (id TEXT PRIMARY KEY,site_id TEXT NOT NULL UNIQUE REFERENCES sites(id),manufacturer TEXT NOT NULL,model TEXT NOT NULL,serial_number TEXT NOT NULL UNIQUE,rated_power_kw REAL NOT NULL CHECK(rated_power_kw>0),map_x REAL NOT NULL CHECK(map_x BETWEEN 0 AND 1),map_y REAL NOT NULL CHECK(map_y BETWEEN 0 AND 1),commissioned_on TEXT NOT NULL,source_mode TEXT NOT NULL DEFAULT 'synthetic');
CREATE TABLE user_sites (user_id TEXT REFERENCES users(id),site_id TEXT REFERENCES sites(id),PRIMARY KEY(user_id,site_id));
CREATE TABLE incidents (id TEXT PRIMARY KEY,site_id TEXT NOT NULL REFERENCES sites(id),family TEXT NOT NULL,title TEXT NOT NULL,tier TEXT NOT NULL CHECK(tier IN ('P0','P1','P2','P3')),status TEXT NOT NULL,suspected_owner TEXT NOT NULL,confirmed_owner TEXT,evidence TEXT NOT NULL,customer_value_ron REAL,operator_value_ron REAL,revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE request_types (id TEXT PRIMARY KEY,label TEXT NOT NULL,family TEXT NOT NULL,owner TEXT NOT NULL,route_to TEXT NOT NULL);
CREATE TABLE crews (id TEXT PRIMARY KEY,name TEXT NOT NULL,area TEXT NOT NULL,owner TEXT NOT NULL,skills_json TEXT NOT NULL,shift_start TEXT NOT NULL,shift_end TEXT NOT NULL);
CREATE TABLE crew_members (crew_id TEXT REFERENCES crews(id),user_id TEXT REFERENCES users(id),PRIMARY KEY(crew_id,user_id));
CREATE TABLE telemetry (id INTEGER PRIMARY KEY,site_id TEXT REFERENCES sites(id),interval_start_utc TEXT NOT NULL,interval_end_utc TEXT NOT NULL,pv_kw REAL,home_kw REAL,import_kw REAL,export_kw REAL,battery_charge_kw REAL,battery_discharge_kw REAL,soc_percent REAL,voltage REAL,temperature REAL,source_mode TEXT NOT NULL,quality TEXT NOT NULL,received_at_utc TEXT NOT NULL);
CREATE TABLE forecasts (id INTEGER PRIMARY KEY,site_id TEXT REFERENCES sites(id),issued_at_utc TEXT NOT NULL,valid_at_utc TEXT NOT NULL,pv_kw REAL,load_kw REAL,method_version TEXT NOT NULL,provenance TEXT NOT NULL);
CREATE TABLE tariff_intervals (id INTEGER PRIMARY KEY,site_id TEXT REFERENCES sites(id),start_utc TEXT NOT NULL,end_utc TEXT NOT NULL,import_ron_kwh REAL NOT NULL,export_ron_kwh REAL NOT NULL,contract_version TEXT NOT NULL,is_assumption INTEGER NOT NULL DEFAULT 1);
CREATE TABLE tasks (id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),site_id TEXT REFERENCES sites(id),type TEXT NOT NULL,energy_kwh REAL CHECK(energy_kwh>0),power_kw REAL CHECK(power_kw>0),profile_json TEXT NOT NULL,deadline_utc TEXT NOT NULL,status TEXT NOT NULL);
CREATE TABLE recommendations (id TEXT PRIMARY KEY,task_id TEXT REFERENCES tasks(id),start_utc TEXT NOT NULL,end_utc TEXT NOT NULL,expires_utc TEXT NOT NULL,saving_ron REAL NOT NULL,assumptions_json TEXT NOT NULL,status TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE reservations (id TEXT PRIMARY KEY,recommendation_id TEXT REFERENCES recommendations(id),area TEXT NOT NULL,start_utc TEXT NOT NULL,end_utc TEXT NOT NULL,power_kw REAL NOT NULL CHECK(power_kw>0),status TEXT NOT NULL,expires_utc TEXT);
CREATE INDEX reservations_scope ON reservations(area,start_utc,end_utc,status);
CREATE TABLE visits (id TEXT PRIMARY KEY,site_id TEXT NOT NULL REFERENCES sites(id),incident_id TEXT NOT NULL REFERENCES incidents(id),author_id TEXT NOT NULL REFERENCES users(id),request_type TEXT NOT NULL REFERENCES request_types(id),priority TEXT NOT NULL CHECK(priority IN ('standard','urgent','immediate_danger')),routed_to TEXT NOT NULL,description TEXT NOT NULL,consent_utc TEXT NOT NULL,status TEXT NOT NULL,created_utc TEXT NOT NULL);
CREATE TABLE media (id TEXT PRIMARY KEY,visit_id TEXT REFERENCES visits(id),private_storage_key TEXT NOT NULL,validation_state TEXT NOT NULL,mime_type TEXT NOT NULL,size_bytes INTEGER NOT NULL,duration_seconds REAL,delete_after_utc TEXT NOT NULL);
CREATE TABLE visit_replies (id TEXT PRIMARY KEY,visit_id TEXT REFERENCES visits(id),author_id TEXT REFERENCES users(id),body TEXT NOT NULL,outcome TEXT NOT NULL,created_utc TEXT NOT NULL);
CREATE TABLE assignments (id TEXT PRIMARY KEY,incident_id TEXT REFERENCES incidents(id),crew_id TEXT REFERENCES crews(id),start_utc TEXT NOT NULL,end_utc TEXT NOT NULL,state TEXT NOT NULL,approver_id TEXT REFERENCES users(id),revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE audit (id TEXT PRIMARY KEY,actor_id TEXT REFERENCES users(id),action TEXT NOT NULL,subject TEXT NOT NULL,created_utc TEXT NOT NULL,decision_version INTEGER);
CREATE TABLE preferences (user_id TEXT PRIMARY KEY REFERENCES users(id),task TEXT NOT NULL,deadline TEXT NOT NULL,notifications TEXT NOT NULL);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),expires_utc TEXT NOT NULL,csrf_hash TEXT NOT NULL);
CREATE TABLE idempotency_keys (user_id TEXT REFERENCES users(id),operation TEXT NOT NULL,key TEXT NOT NULL,response_json TEXT NOT NULL,PRIMARY KEY(user_id,operation,key));
